In Go, `time.Now()` carries a monotonic reading, and `time.Since` uses it. Set the header when the response is committed:

```go
type elapsedWriter struct {
	http.ResponseWriter
	start time.Time
	wrote bool
}

func (w *elapsedWriter) WriteHeader(status int) {
	if !w.wrote {
		w.Header().Set("X-Intake-Elapsed", time.Since(w.start).String())
		w.wrote = true
	}
	w.ResponseWriter.WriteHeader(status)
}

func (w *elapsedWriter) Write(p []byte) (int, error) {
	if !w.wrote {
		w.WriteHeader(http.StatusOK)
	}
	return w.ResponseWriter.Write(p)
}

func IntakeTiming(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		tw := &elapsedWriter{ResponseWriter: w, start: time.Now()}
		next.ServeHTTP(tw, r)
		if !tw.wrote {
			tw.WriteHeader(http.StatusOK)
		}
	})
}
```

This measures elapsed time until response headers are committed.

